-- Re-admit the twice-resealed 2026.11.15.7 provider bundle. The release was
-- re-sealed a second time for the review fixes to the watchdog hardening
-- itself: the shared key is now staged inside a root-owned sibling directory
-- so a bux-planted symlink can never redirect the root-run writer, and the
-- direct-access Caddyfile migrates its previous generated bytes atomically
-- instead of failing re-enrollment. The sealed manifest digest changed from
-- 7531d349e21783765e52b6d33c507a35568b0c8830f23faab1245f26bed48869 to
-- 28ae48475970fd17617292ae3a3b9823769ed3c9c8fc9d9a6774d32199a510ff.
--
-- Migrations are append-only, so this rewrites the 2026.11.15.7 clause inside
-- both provider identity functions: the previous .7 clause appears exactly
-- once in each. Idempotent: a function already carrying the current clause is
-- left as it is.
do $migration$
declare signature text; definition text; anchor text; addition text;
begin
  for signature, anchor, addition in select * from (values
    ('public.hivra_provider_native_identity_valid(jsonb,uuid,uuid)',
     '(p_identity->''bundle''->>''bundleSha256''=''7531d349e21783765e52b6d33c507a35568b0c8830f23faab1245f26bed48869'' and p_identity->''bundle''->>''provisionerVersion''=''2026.11.15.7'')',
     '(p_identity->''bundle''->>''bundleSha256''=''28ae48475970fd17617292ae3a3b9823769ed3c9c8fc9d9a6774d32199a510ff'' and p_identity->''bundle''->>''provisionerVersion''=''2026.11.15.7'')'),
    ('public.hivra_provider_desktop_identity_valid(jsonb,uuid,uuid)',
     '(p_identity->''bundle''->>''bundleSha256''=''7531d349e21783765e52b6d33c507a35568b0c8830f23faab1245f26bed48869'' and p_identity->''bundle''->>''provisionerVersion''=''2026.11.15.7'')',
     '(p_identity->''bundle''->>''bundleSha256''=''28ae48475970fd17617292ae3a3b9823769ed3c9c8fc9d9a6774d32199a510ff'' and p_identity->''bundle''->>''provisionerVersion''=''2026.11.15.7'')')
  ) as patches(signature, anchor, addition)
  loop
    definition := pg_get_functiondef(signature::regprocedure);
    if position(addition in definition) > 0 then
      if position(anchor in definition) > 0 then
        raise exception 'Provider release admission: conflicting .7 clauses present: %', signature;
      end if;
      continue;
    end if;
    if (length(definition) - length(replace(definition, anchor, ''))) / length(anchor) <> 1 then
      raise exception 'Provider release admission anchor mismatch: %', signature;
    end if;
    execute replace(definition, anchor, addition);
  end loop;
end;
$migration$;
